edits.find:
case ({push, pop})
    2'b10: begin
        empty_r <= 1'b0;
        full_r  <= (wp_next == rp);
    end
    2'b01: begin
        full_r  <= 1'b0;
        empty_r <= (rp_next == wp);
    end
    default: begin
    end
endcase

edits.replace:
if (push) begin
    empty_r <= 1'b0;
    full_r  <= (wp_next == rp);
end
if (pop) begin
    full_r  <= 1'b0;
    empty_r <= (rp_next == wp);
end
